/**
 * 检查订单状态
 * 用于H5模式下防止重复支付
 * @returns {Object} { paid: boolean, status: string }
 */
async checkOrderStatus() {
	try {
		// 使用已有的 getCashierOrder 接口检查订单状态
		const res = await getCashierOrder(this.orderId, this.fromType);
		if (res.data) {
			// 根据返回数据判断订单是否已支付
			// 如果 pay_price 为 0 或者订单状态已改变，说明已支付
			const isPaid = res.data.paid === 1 || res.data.pay_price === 0 || res.data.status === 1;
			return {
				paid: isPaid,
				status: res.data.status,
				payPrice: res.data.pay_price
			};
		}
	} catch (err) {
		console.log('检查订单状态失败:', err);
	}
	return { paid: false };
},

